interface VarietyOptions {
  teams?: QuizTeamId[];
  era?: string;
  /** Shared prefix groups related facts so a run asks only one of them (see topicFamily). */
  topic?: string;
  source: string;
}

function v(
  id: string,
  question: string,
  correct: string,
  others: [string, string, string],
  difficulty: QuizQuestion["difficulty"],
  category: QuizQuestion["category"],
  options: VarietyOptions
): QuizQuestion {
  return placeCorrectAnswer({
    id: `var-${id}`,
    topicId: options.topic ?? `variety:${id}`,
    question,
    options: [correct, ...others],
    correctAnswer: correct,
    difficulty,
    category,
    teams: options.teams ?? [],
    era: options.era,
    sourceType: "curated",
    answerType: "objective",
    source: options.source,
  });
}

